#!/usr/bin/env node
// Pablolinguo guard for agent sessions (Claude Code PreToolUse hook, declared in .claude/settings.json).
// It refuses, before the file is written or the command runs, what the build and CI would refuse later:
// editing a migration already in main, writing generated files or .env, bypassing checks, force-pushing,
// turning RLS off. Protocol: the tool call arrives as JSON on stdin; exit code 2 blocks it and stderr
// goes back to the agent. The tests and CI stay the referee (a sed -i can slip past this hook).
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";

const block = (reason) => { process.stderr.write(`✋ Blocked by .claude/hooks/guard.js: ${reason}\n`); process.exit(2); };
const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const GENERATED = ["web/public/runtime.js", "web/public/ui.css", "web/public/ui.js", "web/public/app.js"];

function inMain(rel) {
  for (const ref of ["origin/main", "HEAD"]) {
    try { execFileSync("git", ["cat-file", "-e", `${ref}:${rel}`], { cwd: root, stdio: "ignore" }); return true; } catch { /* not in this ref */ }
  }
  return false;
}

function checkFile(file) {
  const rel = path.relative(root, path.resolve(root, file)).split(path.sep).join("/");
  if (/^supabase\/migrations\/.+\.sql$/.test(rel) && inMain(rel))
    block(`${rel} is already in main: never edit it. Write a new migration (supabase/migrations/<date -u +%Y%m%d%H%M%S>_<subject>.sql).`);
  if (GENERATED.includes(rel)) block(`${rel} is generated by npm run build: edit its source in web/src/ or web/ui/.`);
  const base = path.basename(rel);
  if (/^\.env(\..+)?$/.test(base) && base !== ".env.example") block(`${rel} holds secrets: an agent does not write it. Secrets go in Vercel.`);
}

function checkText(text) {
  if (/disable\s+row\s+level\s+security/i.test(text)) block("RLS is never turned off, not even to debug.");
  if (/\b(using|with\s+check)\s*\(\s*true\s*\)/i.test(text)) block("a policy open to everyone (true) is refused: tie it to auth.uid().");
}

function checkCommand(cmd) {
  if (/--no-verify\b/.test(cmd)) block("--no-verify skips the pre-commit checks.");
  if (/\bgit\s+push\b[^\n]*(\s--force(?!-with-lease)\b|\s-f\b)/.test(cmd)) block("no force push on this repository.");
  if (/\bsupabase\s+db\s+(push|reset)\b/.test(cmd)) block("the hosted database only changes through a reviewed migration, applied by Pi.");
  if (/\bcore\.hooksPath\b/.test(cmd) && !/\.githooks/.test(cmd)) block("the pre-commit hook path stays .githooks.");
  if (/\b(psql|supabase)\b/.test(cmd)) checkText(cmd);
}

const input = JSON.parse(readFileSync(0, "utf8") || "{}");
const t = input.tool_input || {};
if (t.file_path) checkFile(t.file_path);
if (t.notebook_path) checkFile(t.notebook_path);
// SQL rules apply to SQL only (a .sql file or a query), not to the tests and docs that name them.
const sqlFile = /\.sql$/i.test(t.file_path || "");
for (const v of [t.query, ...(sqlFile ? [t.content, t.new_string, ...(t.edits || []).map((e) => e.new_string)] : [])]) if (typeof v === "string") checkText(v);
if (typeof t.command === "string") checkCommand(t.command);
